/** The argument names the operation takes (from the API's own table, so they cannot drift), plus the chat-only names and the revision the chat fills in. */
/**
 * What each landing does, in one plain sentence (card P08b). These are the words the owner is shown when a landing change is drawn up, and the owner's confirmation of that showing is the consent —
 * nothing here reads the owner's sentence for an order, and no message tells the owner what to say. The table is built from the policy's own list of landings, so a landing added to the policy has to be
 * given a sentence here before the code compiles: there is no landing the owner would be offered without a plain description of it.
 */
const LANDING_MEANS_TEXT: Record<(typeof LANDINGS)[number], string> = {
  "integration-branch": "finished work is merged onto the project's integration branch, and nothing reaches main until you or its integrator promotes it",
  "main-automatic": "finished work lands on main by itself once its required checks pass, with no human step",
  "human-promotes": "finished work waits for a person to promote it, and reaches main only when someone does",
};

export const LANDING_MEANS: Readonly<Record<string, string>> = Object.freeze(LANDING_MEANS_TEXT);

/** The landing a command chooses, from the argument the owner's command carries (`project.create` carries it inside its `integration` section), or undefined when the command sets no landing. */
export function landingOf(op: string, args: Readonly<Record<string, unknown>>): string | undefined {
  if (op === "integration.set" || op === "integration.default.set") return typeof args["landing"] === "string" ? args["landing"] : undefined;
  if (op === "project.create") {
    const section = args["integration"];
    const value = section !== null && typeof section === "object" && !Array.isArray(section) ? (section as Record<string, unknown>)["landing"] : undefined;
    return typeof value === "string" ? value : undefined;
  }
  return undefined;
}

